import SwiftUI
struct ArticlesView:View{@StateObject private var model:ArticlesViewModel;let makeDetailModel:(ArticleDTO)->ArticleDetailViewModel;let columns=[GridItem(.flexible()),GridItem(.flexible())];init(model:@autoclosure @escaping()->ArticlesViewModel,makeDetailModel:@escaping(ArticleDTO)->ArticleDetailViewModel){_model=StateObject(wrappedValue:model());self.makeDetailModel=makeDetailModel};var body:some View{NavigationStack{ScrollView{LazyVStack(alignment:.leading,spacing:24){Text(L10n.Articles.subtitle).font(.subheadline).foregroundStyle(.secondary);LazyVGrid(columns:columns,spacing:12){ForEach(ArticleCategory.allCases){category in NavigationLink(value:category){CategoryCard(category:category,count:model.articles(in:category).count)}.buttonStyle(.plain)}};VStack(alignment:.leading){Text(L10n.Articles.recommended).font(.title2.bold());ForEach(Array(model.articles.prefix(5))){article in ArticleRow(article:article,bookmarked:model.isBookmarked(article),toggle:{model.toggleBookmark(article)})}}}.padding(18)}.overlay{if model.isLoading&&model.articles.isEmpty{ProgressView()}}.refreshable{await model.refresh()}.task{await model.appear()}.navigationTitle(L10n.Tab.articles).toolbar{NavigationLink(value:ArticleDestination.bookmarks){Image(systemName:"bookmark")}.accessibilityLabel(Text(L10n.Articles.bookmarks))}.navigationDestination(for:ArticleCategory.self){category in ArticleListView(title:category.title,articles:model.articles(in:category),model:model)}.navigationDestination(for:ArticleDestination.self){_ in ArticleListView(title:L10n.Articles.bookmarks,articles:model.bookmarks,model:model,emptyBookmarks:true)}.navigationDestination(for:ArticleDTO.self){ArticleReaderView(article:$0,model:makeDetailModel($0))}.background(AppTheme.background).accessibilityIdentifier("screen.articles")}}}
private enum ArticleDestination:Hashable{case bookmarks}
private struct CategoryCard:View{let category:ArticleCategory;let count:Int;var body:some View{VStack(alignment:.leading,spacing:16){Image(systemName:category.icon).font(.title2).foregroundStyle(AppTheme.gold);Text(category.title).font(.headline);Text(L10n.Articles.countLld(count)).font(.caption).foregroundStyle(.secondary)}.frame(maxWidth:.infinity,minHeight:112,alignment:.leading).padding(16).background(AppTheme.card).clipShape(RoundedRectangle(cornerRadius:20))}}
private struct ArticleListView:View{let title:String;let articles:[ArticleDTO];@ObservedObject var model:ArticlesViewModel;var emptyBookmarks=false;var body:some View{Group{if articles.isEmpty{ContentUnavailableView(emptyBookmarks ? L10n.Articles.Bookmarks.empty:L10n.Articles.empty,systemImage:"bookmark.slash")}else{List(articles){article in ArticleRow(article:article,bookmarked:model.isBookmarked(article),toggle:{model.toggleBookmark(article)}).listRowBackground(AppTheme.card)}.listStyle(.plain)}}.navigationTitle(title).appScreenBackground()}}
private struct ArticleRow:View{let article:ArticleDTO;let bookmarked:Bool;let toggle:()->Void;var body:some View{NavigationLink(value:article){HStack(spacing:12){Image(systemName:article.appCategory.icon).foregroundStyle(AppTheme.gold).frame(width:38,height:38).background(AppTheme.gold.opacity(0.12),in:RoundedRectangle(cornerRadius:11));VStack(alignment:.leading){Text(article.title).font(.headline).lineLimit(2);Text(L10n.Articles.minutesLld(article.readingMinutes)).font(.caption).foregroundStyle(.secondary)};Spacer();Button(action:toggle){Image(systemName:bookmarked ? "bookmark.fill":"bookmark")}.buttonStyle(.borderless)}}.accessibilityIdentifier("article.row.\(article.slug)")}}
private struct ArticleReaderView:View{let article:ArticleDTO;@StateObject private var model:ArticleDetailViewModel;init(article:ArticleDTO,model:@autoclosure @escaping()->ArticleDetailViewModel){self.article=article;_model=StateObject(wrappedValue:model())};var body:some View{ScrollView{VStack(spacing:0){hero;if let detail=model.detail{bodyView(detail)}else if model.failed{ContentUnavailableView(L10n.Content.Error.title,systemImage:"wifi.exclamationmark").padding()}else{ProgressView().padding(40)}}}.background(AppTheme.background).ignoresSafeArea(edges:.top).toolbar{Button{model.toggleBookmark()}label:{Image(systemName:model.isBookmarked ? "bookmark.fill":"bookmark")}}.task{await model.appear()}.accessibilityIdentifier("screen.articleReader")};private func bodyView(_ detail:ArticleDetailDTO)->some View{VStack(alignment:.leading,spacing:26){Text(detail.summary).font(.title3).foregroundStyle(.secondary);ForEach(Array(detail.sections.enumerated()),id:\.offset){_,section in VStack(alignment:.leading){Text(section.heading).font(.title2.bold());Text(section.body).lineSpacing(6)}}}.padding(20)};private var hero:some View{ZStack(alignment:.bottomLeading){LinearGradient(colors:[AppTheme.gold.opacity(0.8),AppTheme.graphite],startPoint:.topLeading,endPoint:.bottomTrailing);LinearGradient(colors:[.clear,.black.opacity(0.94)],startPoint:.top,endPoint:.bottom);VStack(alignment:.leading){Text(article.title).font(.system(size:34,weight:.bold,design:.rounded)).foregroundStyle(.white);Label(L10n.Articles.minutesLld(article.readingMinutes),systemImage:"clock").foregroundStyle(.white.opacity(0.8))}.padding(20)}.frame(height:390).clipped()}}
extension ArticleDTO{var appCategory:ArticleCategory{switch category{case "fundamentals":.basics;case "bowls_heat":.heat;default:ArticleCategory(rawValue:category) ?? .basics}}}
